#!/usr/bin/env python3
"""WX1 analysis (registration planned/WX1_PREREG.md). Reads out/wx1/results.json."""
import json
R = json.load(open('out/wx1/results.json')); P = []
def chk(n, ok, t): P.append((n, ok, t)); print('PASS' if ok else 'FAIL', n, t)
pc = lambda v: f'{100 * v:.1f} %'
rng = {'houston': (0.08, 0.16), 'dfw': (0.06, 0.12)}
chk('W1', all(rng[m][0] <= R[m]['wet'] <= rng[m][1] for m in R), ', '.join(f"{m} wet {pc(R[m]['wet'])}" for m in R))
chk('W2', all(0.003 <= R[m]['thunder'] <= 0.025 for m in R), ', '.join(f"{m} thunder {pc(R[m]['thunder'])}" for m in R))
chk('W3', all(0.04 <= R[m]['gust40'] <= 0.14 for m in R), ', '.join(f"{m} gust>=40 {pc(R[m]['gust40'])}" for m in R))
chk('W4', all(0.015 <= R[m]['hard'] <= 0.07 for m in R), ', '.join(f"{m} hard-stop {pc(R[m]['hard'])}" for m in R))
def w5(m): b = R[m]['band']; return sum(1 for h in b if h['p'] >= 0.1), sum(1 for h in b if h['code'] in (95, 96, 99))
chk('W5', all(w5(m)[0] <= 3 and w5(m)[1] == 0 for m in R), ', '.join(f"{m} wet {w5(m)[0]}/10, thunder {w5(m)[1]}/10" for m in R))
chk('W6', all(R[m]['medGustBand'] >= 1.5 * R[m]['medGustDay'] for m in R), ', '.join(f"{m} band median gust {R[m]['medGustBand']} vs daytime {R[m]['medGustDay']} km/h ({R[m]['medGustBand'] / R[m]['medGustDay']:.2f}x)" for m in R))
n = sum(1 for _, ok, _ in P if ok)
L = ['# WX1 results table (generated by planned/wx1_analyze.py)', '', f'{n} of {len(P)} predictions passed.', ''] + [f'- {"PASS" if ok else "FAIL"} {a}: {t}' for a, ok, t in P]
L += ['', '| Metro | Daytime hours | Wet >=0.1 mm | Rain >=1 mm | Heavy >=2.5 mm | Thunder | Gust >=40 | Gust >=55 | Hard-stop |', '|---|---|---|---|---|---|---|---|---|']
L += [f"| {m} | {r['n']} | {pc(r['wet'])} | {pc(r['rain1'])} | {pc(r['heavy'])} | {pc(r['thunder'])} | {pc(r['gust40'])} | {pc(r['gust55'])} | {pc(r['hard'])} |" for m, r in R.items()]
L += ['', 'Windy test hours (bandHours 0.85-0.95, first 10):'] + [f"- {m}: " + '; '.join(f"{h['t']} precip {h['p']} mm code {h['code']} gust {h['gust']} km/h 120 m wind {h['w120']}" for h in r['band']) for m, r in R.items()]
open('planned/wx1_results_table.md', 'w').write('\n'.join(L) + '\n'); print(f'{n} of {len(P)} passed; wrote planned/wx1_results_table.md')
